   private IWebSocketListener listener;

   private String myChannel;
   private String myInstance;
   private String myWebSocket;
   private static Boolean isReconnecting = false;
   private static Boolean isStarting = false;

   public static JWebSocketClient getInstance() {
      if (instance == null) {
         instance = new JWebSocketClient();
      }
      return instance;
   }

   public boolean isConnected() {
      try {
         return websocketClient != null && websocketClient.getConnection().isOpen();
      } catch (Exception e) {
         return false;
      }
   }

   public void start(String userEmail, String userInstance, String webSocketHost, IWebSocketListener listener) {
      this.myChannel = "uc_" + userEmail.replace("@", "_").replace(".", "_");
      this.myInstance = userInstance + "." + userEmail;
      this.myWebSocket = webSocketHost + "/v1/service/" + myInstance;
      this.listener = listener;

      if (!isConnected() && !isStarting) {
         isStarting = true;
         new JStartWebSocket().run();
      }
   }

   public void stop() {
      try {
         if (isConnected()) {
            websocketClient.close();
         }
      } catch (Exception e) {
      } finally {
         websocketClient = null;
      }
   }

