```java
package org.java_websocket.drafts;

import org.java_websocket.exceptions.InvalidHandshakeException;
import org.java_websocket.handshake.*;

public class Draft_OCPP16 extends Draft_17 {

    @Override
    public HandshakeState acceptHandshakeAsServer(ClientHandshake handshakedata) throws InvalidHandshakeException {
        if (super.acceptHandshakeAsServer(handshakedata) == HandshakeState.NOT_MATCHED)
            return HandshakeState.NOT_MATCHED;

        if (!handshakedata.hasFieldValue("Sec-WebSocket-Protocol"))
            return HandshakeState.NOT_MATCHED;

        if (handshakedata.getFieldValue("Sec-WebSocket-Protocol").equalsIgnoreCase("ocpp1.6")) {
            return HandshakeState.MATCHED;
        } else {
            return HandshakeState.NOT_MATCHED;
        }
    }

    @Override
    public HandshakeState acceptHandshakeAsClient(ClientHandshake request, ServerHandshake response) throws InvalidHandshakeException {
        if (super.acceptHandshakeAsClient(request, response) == HandshakeState.NOT_MATCHED)
            return HandshakeState.NOT_MATCHED;

        if (!request.hasFieldValue("Sec-WebSocket-Protocol"))
            return HandshakeState.NOT_MATCHED;

        if (request.getFieldValue("Sec-WebSocket-Protocol").equalsIgnoreCase("ocpp1.6"))
            return HandshakeState.MATCHED;
        return HandshakeState.NOT_MATCHED;
    }

    @Override
    public ClientHandshakeBuilder postProcessHandshakeRequestAsClient(ClientHandshakeBuilder request) {
        super.postProcessHandshakeRequestAsClient(request);
        request.put("Sec-WebSocket-Protocol", "ocpp1.6");
        return request;
    }

    @Override
    public HandshakeBuilder postProcessHandshakeResponseAsServer(ClientHandshake request, ServerHandshakeBuilder response) throws InvalidHandshakeException {
        HandshakeBuilder result = super.postProcessHandshakeResponseAsServer(request, response);
        result.put("Sec-WebSocket-Protocol", "ocpp1.6");
        return result;
    }

    @Override
    public Draft copyInstance() {
        return new Draft_OCPP16();
    }
}

