            mCountForReconnect++;
            delay = getCurrentFibonacci(mCountForReconnect);
        } else if (webSocketClient.isOpen()) {
            tryReconnecting = false;
            mCountForReconnect = 1;
            delay = 0;
        } else {
            mCountForReconnect++;
            delay = getCurrentFibonacci(mCountForReconnect);
        }

        if (delay != 0) {
            handler.postDelayed(runnableTimer, delay * 1000);
        }
    }

