    public static int getCurrentFibonacci(int item) {
        int maxNumber = 1000;
        int previousNumber = 0;
        int nextNumber = 1;

        int iterator=0;
        for (int i = 1; i <= maxNumber; ++i) {
            int sum = previousNumber + nextNumber;
            previousNumber = nextNumber;
            nextNumber = sum;
            if(iterator++ == item){
                return nextNumber;
            }
        }
        return maxNumber;
    }
}
