Here is a quick example of how this can be achieved. In your case, checking the message type would by done by parsing JSON.
```java
import java.util.concurrent.*;

import java.net.*;

import org.java_websocket.server.*;
import org.java_websocket.client.*;
import org.java_websocket.*;
import org.java_websocket.handshake.*;

public class Main extends WebSocketServer {
	public static void main(String[] args) throws Throwable {
		Main main = new Main();
		main.start();
		Thread.sleep(100); // just to make sure that server has started
		Client client = new Client(URI.create("ws://localhost:"+main.getPort()));
		new Thread(client).start();
		Thread.sleep(1000);
		client.runExample();
	}

	public void onError(WebSocket socket, Exception e) {
		e.printStackTrace();
	}

	public void onMessage(WebSocket socket, String msg) {
		socket.send("result: 4");
	}

	public void onClose(WebSocket socket, int code, String msg, boolean remote) {}

	public void onOpen(WebSocket socket, ClientHandshake handshake) {}

	public void onStart() {}
}

class Client extends WebSocketClient {
	volatile CompletableFuture<String> awaitedResponse;
	volatile String expectedType;

	public Client(URI uri) {
		super(uri);
	}

	public void onOpen(ServerHandshake handshake) {
	}

	public void onError(Exception e) {
		e.printStackTrace();
	}

	public void onClose(int code, String msg, boolean remote) {
	}

	public void onMessage(String msg) {
		// check if the message is of expected type, and not some async message that got inbetween
		if(awaitedResponse != null && msg.startsWith(expectedType)) {
			awaitedResponse.complete(msg);
			awaitedResponse = null;
			expectedType = null;
		} else {
			// handle asynchronous message
			System.out.println("Async message " + msg);
		}
	}

	/* The reason why query is sent from this method is that in theory,
	 * the response could arrive before we've set up the handle
	 * (in practice, that only happens on localhost) */
	String awaitResponse(String query, String type) throws InterruptedException {
		awaitedResponse = new CompletableFuture<>();
		expectedType = type;
		send(query);
		try {
			return awaitedResponse.get();
		} catch(ExecutionException e) {
			throw new RuntimeException(e.getCause());
		}
	}

	public void runExample() throws InterruptedException {
		String response1 = awaitResponse("What is 2+2?", "result");
		System.out.println("Got response: '" + response1 + "'");

		String response2 = awaitResponse("What is 1+3?", "result");
		System.out.println("Got response: '" + response2 + "'");
	}
}
```

EDIT: now that I think about it, you might be better off using a blocking queue and checking if message is synchronous before pushing to it. That way, you don't need to worry about the race condition between sending and waiting.

