**Describe the solution you'd considered**
I don't want to deploy another web server (like `com.sun.net.httpserver.HttpServer`) and redirect WS calls to the WS port, because two ports will be taken.

I've dived into sources and it seems managed to write a custom `Draft` implementation that handles GET requests. There are snippets that make the server return `<h1>Requested path: ${path}</h1>` for HTTP GET requests to `path`, and WS continues to work too (written in Kotlin, library version 1.4.0):

```kt
val ClientHandshake.isHttp: Boolean get() = this.getFieldValue("Upgrade").isNullOrBlank()

class HttpDraft : Draft() {

  private companion object {

    private const val PATH_FIELD = "X-My-Path"
  }

  override fun acceptHandshakeAsServer(handshakedata: ClientHandshake): HandshakeState {
    return when (handshakedata.isHttp) {
      true -> HandshakeState.MATCHED
      false -> HandshakeState.NOT_MATCHED
    }
  }

  override fun postProcessHandshakeResponseAsServer(request: ClientHandshake, response: ServerHandshakeBuilder): HandshakeBuilder {
    response.put(PATH_FIELD, request.resourceDescriptor)
    return response
  }

  override fun createHandshake(handshakedata: Handshakedata, withcontent: Boolean): List<ByteBuffer> {
    val content = "<h1>Requested path: ${handshakedata.getFieldValue(PATH_FIELD)}</h1>".toByteArray()

    val header = Charsetfunctions.asciiBytes(
      "HTTP/1.0 200 OK\r\n" +
      "Mime-Version: 1.0\r\n" +
      "Content-Type: text/html\r\n" +
      "Content-Length: ${content.size}\r\n" +
      "Connection: close\r\n" +
      "\r\n"
    )

    val bytebuffer = ByteBuffer.allocate(content.size + header.size)
    bytebuffer.put(header)
    bytebuffer.put(content)
    bytebuffer.flip()
    return listOf(bytebuffer)
  }

  override fun getCloseHandshakeType(): CloseHandshakeType {
    return CloseHandshakeType.NONE
  }

  override fun copyInstance(): Draft {
    return this
  }

  override fun reset() {
    // nop
  }

  override fun translateFrame(buffer: ByteBuffer): List<Framedata> {
    throw Exception("This draft doesn't work with frames")
  }

  override fun processFrame(webSocketImpl: WebSocketImpl, frame: Framedata) {
    throw Exception("This draft doesn't work with frames")
  }

  override fun createBinaryFrame(framedata: Framedata): ByteBuffer {
    throw Exception("This draft doesn't work with frames")
  }

  override fun createFrames(binary: ByteBuffer, mask: Boolean): List<Framedata> {
    throw Exception("This draft doesn't work with frames")
  }

  override fun createFrames(text: String, mask: Boolean): List<Framedata> {
    throw Exception("This draft doesn't work with frames")
  }

  override fun postProcessHandshakeRequestAsClient(request: ClientHandshakeBuilder): ClientHandshakeBuilder {
    throw Exception("This draft can't be used on a client")
  }

  override fun acceptHandshakeAsClient(request: ClientHandshake, response: ServerHandshake): HandshakeState {
    throw Exception("This draft can't be used on a client")
  }
}
