```

public class TestWebSocketServer {

    private final TestWebSocketServerAction webSocketServerAction;

    private HashMap<String, Boolean> toSendManual = new HashMap<>();

    public TestWebSocketServer(ResourceLoader resourceLoader, int port, UserTokenService userTokenService, Environment environment) throws IOException, KeyStoreException, NoSuchAlgorithmException, CertificateException, UnrecoverableKeyException, KeyManagementException {


        webSocketServerAction = new TestWebSocketServerAction(port);

        webSocketServerAction.setUserTokenService(userTokenService);

        // load up the key store
        final String STORE_TYPE = environment.getProperty("server.ssl.key-store-type");
        final String STORE_PASSWORD = environment.getProperty("server.ssl.key-store-password");
        final String KEY_PASSWORD = environment.getProperty("server.ssl.key-password");

        KeyStore ks = KeyStore.getInstance(STORE_TYPE);
        File kf = resourceLoader.getResource(environment.getProperty("server.ssl.key-store")).getFile();
        ks.load(new FileInputStream(kf), STORE_PASSWORD.toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        kmf.init(ks, KEY_PASSWORD.toCharArray());
        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ks);

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);


        SSLParameters sslParameters = new SSLParameters();
        // This is all we need
        sslParameters.setNeedClientAuth(true);
        sslParameters.setProtocols(new String[]{"TLSv1.1", "TLSv1.2", "TLSv1.3"});

        webSocketServerAction.setConnectionLostTimeout(5);

        webSocketServerAction.setWebSocketFactory(new SSLParametersWebSocketServerFactory(sslContext, sslParameters));

        for (WebsocketMessageType websocketMessageType : WebsocketMessageType.values()) {

            toSendManual.put(websocketMessageType.getLabel(), false);



            webSocketServerAction.getEndpoints().put(websocketMessageType.getUrlPath(),
                    socket -> {


                        while (true) {
                            if (toSendManual.get(websocketMessageType.getLabel())) {
                                log.info("Start send message : {}", websocketMessageType.getLabel());
                                File fileRead = null;
                                try {
                                    fileRead = ResourceUtils.getFile(websocketMessageType.getFilePath());
                                } catch (FileNotFoundException e) {
                                    e.printStackTrace();
                                }

                                webSocketServerAction.broadcast(FileUtils.readFileToString(fileRead, "UTF8").replaceAll("\\$\\{(.+?)\\}", "" + System.currentTimeMillis()));

                                if (socket.isOpen()) {

                                    socket.send(FileUtils.readFileToString(fileRead, "UTF8").replaceAll("\\$\\{(.+?)\\}", "" + System.currentTimeMillis()));
                                } else {
                                    log.error("Socket is closed : {}", websocketMessageType.getLabel());

                                }
                                toSendManual.put(websocketMessageType.getLabel(), false);
                            }
                        }
                    });

        }



        webSocketServerAction.start();

    }

    public void webSocketSendCustomData(WebsocketMessageType messageType) {
        toSendManual.put(messageType.getLabel(), true);
    } }

