public class TestWebSocketClient {

    private TestWebSocketClientAction webSocketClient;

    private BeanFactory beanFactory;


    private TestConfig config;

    public TestWebSocketClient() {
    }

    public TestWebSocketClient(TestConfig config, BeanFactory beanFactory)
            throws InterruptedException, NoSuchAlgorithmException, UnrecoverableKeyException, KeyStoreException, IOException, CertificateException, URISyntaxException, KeyManagementException {
        this.webSocketClient = configureWebSocket(config, beanFactory);
        this.connect();
    }

    private TestWebSocketClientAction configureWebSocket(TestConfig config, BeanFactory beanFactory)
            throws URISyntaxException, KeyStoreException, IOException, NoSuchAlgorithmException, CertificateException, UnrecoverableKeyException, KeyManagementException, InterruptedException {
        if (config != null) {
            this.config = config;
        }

        TestWebSocketClientAction webSocketClientInternal = null;
       
       
        webSocketClientInternal = new TestWebSocketClientAction(config, beanFactory);

        KeyStore ks = KeyStore.getInstance(config.getStoreType());
        File keyStoreFile = config.getKeyStoreFile();
        ks.load(new FileInputStream(keyStoreFile), config.getStorePassword().toCharArray());

        KeyManagerFactory kmf = KeyManagerFactory.getInstance("SunX509");
        KeyStore kms = KeyStore.getInstance(config.getKeyStoreType());
        File storeFile = config.getKeyStoreFile();
        kms.load(new FileInputStream(storeFile), config.getKeyStorePassword().toCharArray());
        kmf.init(kms, config.getKeyStorePassword().toCharArray());

        TrustManagerFactory tmf = TrustManagerFactory.getInstance("SunX509");
        tmf.init(ks);

        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(kmf.getKeyManagers(), tmf.getTrustManagers(), null);

        SSLParameters sslParameters = new SSLParameters();
        // This is all we need
        sslParameters.setNeedClientAuth(true);

        sslParameters.setProtocols(new String[]{"TLSv1.1", "TLSv1.2", "TLSv1.3"});
        // sslParameters.setEndpointIdentificationAlgorithm("HTTPS");

        SSLSocketFactory factory = sslContext.getSocketFactory();

        webSocketClientInternal.setSocketFactory(factory);
        webSocketClientInternal.setConnectionLostTimeout(config.getConnectionLostTimeout());

        //reused address
        // webSocketClientInternal.setReuseAddr(true);
        // webSocketClientInternal.setTcpNoDelay(true);
        webSocketClientInternal.connect();
        return webSocketClientInternal;
    }


    public boolean isClosed() {
        return this.webSocketClient == null ? true : this.webSocketClient.isClosed() || this.webSocketClient.isClosing()
                || this.webSocketClient.isFlushAndClose();
    }


    public void connect() {
        this.webSocketClient.addHeader("Authorization", config.getToken());
        this.webSocketClient.connect();
    }

    public void reconnect() {
        this.webSocketClient.reconnect();
    }

    public void refreshAuthToken(String authToken) {
        this.webSocketClient.addHeader("Authorization", config.getToken());
    }
}

